import type { On } from 'claude-code'

import type { ModState } from '../state'
import { isScreenedOrigin, screenInbound, screenOutbound } from './screen'

/**
 * `session.receive` and `session.send` (ADR-451 item 3): an in-process
 * pattern screen for what reaches the session from a peer or relay, and for
 * what leaves it for another agent. Off unless `deliveryScreen` is on.
 *
 * Tighten-only: an inbound hit is consumed (nothing is queued, shown or read
 * by the model), an outbound hit is refused; text is never rewritten and never
 * allowed past another hook's refusal (the screen only answers without `next`
 * on a hit). The person's own prompts (Remote Control, scheduled triggers) and
 * the lead's messages are not screened. The rule id is named, never the
 * matched text. Any failure passes the message on.
 */
export function registerDelivery(on: On, state: ModState) {
  const d = state.delivery
  d.enabled = true

  on('session.receive', async ($, e, next) => {
    const rule = isScreenedOrigin(e.origin.kind) ? screenInbound(e.text) : undefined
    if (!rule) return next(e)
    d.consumed += 1
    await state.say({ level: 'error', text: `ruflo deliveryScreen: dropped a ${e.origin.kind} delivery (rule: ${rule})` })
    return { consumed: `ruflo deliveryScreen: ${rule}` }
  }).catch(($, e, next) => next(e)) // fail open

  on('session.send', async ($, e, next) => {
    const rule = screenOutbound(e.text)
    if (!rule) return next(e)
    d.blocked += 1
    await state.say({ level: 'error', text: `ruflo deliveryScreen: held back an outgoing message (rule: ${rule})` })
    return { isDelivered: false, reason: `ruflo deliveryScreen refused to send this message (${rule}); remove it and send again` }
  }).catch(($, e, next) => next(e))
}

files.hooks/describe/index.ts:
import type { On } from 'claude-code'

import type { ModState } from '../state'
import { withHint } from './hints'

/**
 * `tool.describe` (ADR-451): adds one static usage hint to the description of
 * a few ruflo MCP tools, once per tool per session. Off unless the
 * `toolHints` option is on. It only appends text: placement (`isDeferred`)
 * and the engine's own description are kept, and a tool not in the hint
 * table, or from any other server, is left exactly as it came.
 */
export function registerDescribe(on: On, state: ModState) {
  state.toolHints.enabled = true

  on('tool.describe', { tool: /^mcp__(?:plugin_ruflo-core_ruflo|claude-flow|ruflo)__/ }, async (_$, e, next) => {
    const result = await next(e)
    const description = withHint(e.tool, result.description)
    if (description === result.description || typeof description !== 'string') return result
    state.toolHints.described.add(e.tool)
    return { ...result, description }
  })
}

files.hooks/guard/index.ts:
import type { On } from 'claude-code'

import { cachedFile, type Read } from '../files'
import type { GuidanceHooks } from '../guidance'
import { redraw, under, type ModState } from '../state'
import { dangerousCommandVerdict } from './dangerous-command'
import { parseProjection, policyOpinion, PROJECTION_PATH, type Projection } from './policy'
import { researchCheck } from './research'
import { stricter, type Verdict } from './verdict'

/** What `tool.check` answers when ruflo's own check could not run. */
export const CHECK_FAILED: Verdict = {
  decision: 'ask',
  reason: 'ruflo: its policy check could not run, so this call is put to you instead of allowed',
}

/**
 * Ruflo's opinion on one call, from the dangerous-command list and the read
 * policy projection; `observed` is set when observe mode would have acted.
 */
export function opinionOf(
  state: ModState,
  read: Read<Projection>,
  tool: string,
  input: unknown,
): { verdict?: Verdict; observed?: string } {
  const danger = dangerousCommandVerdict(tool, input)
  if (danger) return { verdict: danger }

  if (read.kind === 'absent') {
    state.policy = 'none'
    return {}
  }
  if (read.kind === 'error') {
    // The CLI writes a projection only where policy is in force: one that
    // exists and cannot be read fails closed, by one step.
    state.policy = 'unreadable'
    return { verdict: { ...CHECK_FAILED, reason: `ruflo: policy projection unreadable (${read.message}); asking instead of allowing` } }
  }
  state.policy = read.value.mode
  const { verdict, wouldBe } = policyOpinion(read.value, tool, input)
  return wouldBe ? { observed: wouldBe } : { verdict }
}

/**
 * `tool.check`: tighten only. The chain runs first (engine rules, mode, the
 * PreToolUse hooks, every plugin beneath); ruflo's opinion is merged with
 * `stricter`, so an allow may become an ask or a deny and nothing ever
 * becomes looser. The dangerous-command list always applies; ruflo policy
 * applies when the CLI projected rules for Claude Code tools.
 */
export function registerGuard(on: On, state: ModState, guidance?: GuidanceHooks) {
  const projection = cachedFile(() => under(state, PROJECTION_PATH), parseProjection)
  const research = researchCheck(state)

  on('tool.check', async ($, e, next) => {
    const task = guidance?.active()
    const chain = await next(e)
    const tool = typeof e.tool === 'string' ? e.tool : ''
    const read = await projection({ stat: path => $.fs.stat(path), read: path => $.fs.read(path) })
    const { verdict, observed } = opinionOf(state, read, tool, e.input)
    if (observed) {
      state.observed++
      try {
        $.ui.log(`ruflo policy (observe): ${tool} ${observed}`, { to: 'debug' })
      } catch {
        // a refused log never turns an observation into a failure
      }
    }
    // The research guard (ADR-440) sees what ruflo's own opinion left standing.
    const merged = await research({ stat: path => $.fs.stat(path), read: path => $.fs.read(path) }, tool, stricter(chain, verdict))
    if (merged !== chain) {
      state.tightened++
      redraw(state)
    }
    guidance?.check(task, merged.decision)
    return merged
  }).catch(async ($, e, next) => {
    // ruflo could not judge. Fail closed by one step: the chain's verdict
    // stands where it is already ask or deny; an allow is put to the person.
    const chain = await next(e).catch(() => undefined)
    const result = chain ? stricter(chain, CHECK_FAILED) : CHECK_FAILED
    guidance?.check(guidance.active(), result.decision)
    return result
  })
}

files.hooks/guidance/index.ts:
import { cachedFile, type FileHost } from '../files'
import type { ModOptions } from '../options'
import { under, type ModState } from '../state'
import { finishTask, flushObservations, newRunId, OBSERVATIONS_DIR, type ActiveTask } from './observations'
import { MAX_PROJECTION_BYTES, parseProjection, PROJECTION_PATH, selectGuidance } from './projection'

export type GuidanceHooks = {
  start: () => void
  prompt: (text: string, fs: FileHost) => Promise<string | undefined>
  active: () => ActiveTask | undefined
  check: (task: ActiveTask | undefined, decision: unknown) => void
  tool: (task: ActiveTask | undefined, event: unknown, result: { deny?: unknown; isError?: boolean }) => void
  complete: (turnId: unknown, isAborted?: boolean) => void
  end: () => void
  flush: (fs: { read: (path: string) => Promise<string>; write: (path: string, text: string) => Promise<void> }) => Promise<void>
}

/**
 * Optional feature helpers composed INSIDE the existing hooks. Claude Code
 * permits one unmatched handler per event per plugin. No second tool, prompt,
 * session or turn handler is registered, and no new host capability is added.
 */
export function createGuidance(state: ModState, options: ModOptions): GuidanceHooks | undefined {
  if (!options.guidanceContext && !options.guidanceLearning) return undefined
  const s = state.guidance
  const projection = cachedFile(() => under(state, PROJECTION_PATH), parseProjection)

  return {
    start() {
      if (!s.runId) { s.runId = newRunId(); s.status = 'missing' }
    },
    async prompt(text, fs) {
      if (!s.runId) return undefined
      if (options.guidanceLearning) finishTask(s, 'interrupted')
      const read = await projection({
        stat: async path => {
          const stat = await fs.stat(path)
          if (stat.isLink || stat.size > MAX_PROJECTION_BYTES) throw new Error('invalid guidance file')
          return stat
        },
        read: fs.read,
      })
      s.status = read.kind === 'ok' ? 'ready' : read.kind === 'absent' ? 'missing' : 'unreadable'
      if (read.kind !== 'ok') return undefined
      const selected = selectGuidance(text, read.value)
      if (options.guidanceLearning) {
        s.active = { taskId: ++s.taskSeq, projection: read.value, ruleIds: options.guidanceContext ? selected.ids : [], checks: { allow: 0, ask: 0, deny: 0 }, tools: { ok: 0, error: 0, denied: 0 }, toolIds: new Set(), idsDropped: 0 }
      }
      return options.guidanceContext ? selected.context : undefined
    },
    active: () => s.active,
    check(task, decision) {
      if (task && (decision === 'allow' || decision === 'ask' || decision === 'deny')) task.checks[decision]++
    },
    tool(task, event, result) {
      if (!task) return
      try {
        const id = (event as { tool_use_id?: unknown }).tool_use_id
        if (typeof id === 'string') {
          if (task.toolIds.has(id)) return
          if (task.toolIds.size >= 256) { task.idsDropped++; return }
          task.toolIds.add(id)
        }
        if (result.deny !== undefined) task.tools.denied++
        else if (result.isError === true) task.tools.error++
        else task.tools.ok++
      } catch {
        // Observation failure preserves the underlying tool's settled result.
      }
    },
    complete(turnId, isAborted) {
      if (!options.guidanceLearning || !s.runId) return
      if (typeof turnId === 'string') {
        if (s.seenTurns.has(turnId)) return
        if (s.seenTurns.size < 256) s.seenTurns.add(turnId)
      }
      finishTask(s, isAborted ? 'aborted' : 'completed')
    },
    end() {
      if (options.guidanceLearning && s.runId) finishTask(s, 'interrupted')
    },
    async flush(fs) {
      if (options.guidanceLearning && s.runId) await flushObservations(s, under(state, `${OBSERVATIONS_DIR}/${s.runId}.json`), fs)
    },
  }
}

files.hooks/learn/index.ts:
import type { EngineInterface, On } from 'claude-code'

import { isMissing } from '../files'
import type { GuidanceHooks } from '../guidance'
import { redraw, under, type ModState } from '../state'
import { appendRecords, EDIT_TOOLS, editedFile, MAX_LINES, PENDING_PATH, rufloSessionId, SESSION_PATH } from './insights'

/** Written early once this many edits wait, so a long turn holds little. */
const FLUSH_AT = 50

/**
 * Writes the waiting edit records to pending-insights.jsonl. A file that
 * exists but cannot be read is never overwritten: the records wait (capped)
 * and the classic consolidator's file stays as it was.
 */
export async function flushEdits($: EngineInterface, state: ModState): Promise<void> {
  if (state.edits.length === 0) return
  const records = state.edits.splice(0)
  try {
    const session = await $.fs.read(under(state, SESSION_PATH)).catch(() => undefined)
    const sessionId = rufloSessionId(session)
    const existing = await $.fs.read(under(state, PENDING_PATH)).catch((error: unknown) => {
      if (isMissing(error)) return ''
      throw error
    })
    await $.fs.write(under(state, PENDING_PATH), appendRecords(existing, records.map(r => ({ ...r, sessionId }))))
  } catch (error) {
    state.edits.unshift(...records)
    state.edits.splice(0, Math.max(0, state.edits.length - MAX_LINES))
    try {
      $.ui.log(`ruflo mods: edit records not written yet (${String((error as Error)?.message ?? error)})`, { to: 'debug' })
    } catch {
      // nothing more to do: the records wait for the next turn
    }
  }
}

/**
 * `tool.call` on the edit tools: hook-handler.cjs `post-edit` in-process,
 * recording each finished edit (a failed one with `success: false`, ADR-174;
 * a denied one never ran, as PostToolUse never fires for it). Written per
 * turn at `turn.complete`, and at `session.end`.
 */
export function registerLearn(on: On, state: ModState, guidance?: GuidanceHooks) {
  on('tool.call', async ($, e, next) => {
    const task = guidance?.active()
    const result = await next(e)
    guidance?.tool(task, e, result)
    if (!state.owned.has('post-edit') || !EDIT_TOOLS.has(e.tool) || result.deny !== undefined) return result

    state.edits.push({
      type: 'edit',
      file: editedFile(e),
      success: result.isError !== true,
      timestamp: Date.now(),
      sessionId: null,
    })
    state.editCount++
    redraw(state)
    if (state.edits.length >= FLUSH_AT) await flushEdits($, state)
    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (guidance) {
      guidance.complete(e.turnId, e.isAborted)
      await guidance.flush({ read: path => $.fs.read(path), write: (path, text) => $.fs.write(path, text) })
    }
    await flushEdits($, state)
    return result
  })

  on('session.end', async ($, e, next) => {
    if (guidance) {
      guidance.end()
      await guidance.flush({ read: path => $.fs.read(path), write: (path, text) => $.fs.write(path, text) })
    }
    await flushEdits($, state)
    return next(e)
  })
}

files.hooks/noun.ts:
import type { EngineInterface, On } from 'claude-code'

import type { RufloSnapshot } from '../types'
import { redraw, setSegment, sortedSegments, type ModState } from './state'
import { bindToasts } from './toast'

/** The snapshot `$.ruflo.snapshot()` answers: copies, never live state. */
export function snapshotOf(s: ModState): RufloSnapshot {
  return {
    owned: [...s.owned],
    routed: s.routed,
    lastRoute: s.lastRoute ? { ...s.lastRoute } : null,
    policy: s.policy,
    tightened: s.tightened,
    observed: s.observed,
    edits: s.editCount,
    ...(s.budget.limit !== undefined
      ? { budget: { level: s.budget.level, ...(s.budget.usd !== undefined ? { usd: s.budget.usd } : {}), limit: s.budget.limit } }
      : {}),
    segments: sortedSegments(s).map(([id, text]) => ({ id, text })),
  }
}

/**
 * `engine.create`: adds `$.ruflo` (contract: ../types/index.d.ts) and takes
 * the status line drawer from the `$` built beneath, so every redraw goes
 * through one place and a refused `ui.status` never fails a hook.
 *
 * Another plugin's `$.ruflo.<method>(input)` runs as an event through the
 * chain, these methods its core; where this mod is not seated the noun is
 * absent and such a call rejects, which its callers catch.
 */
export function registerNoun(on: On, state: ModState) {
  on('engine.create', async ($, e, next) => {
    const beneath = await next(e)

    state.draw = text => {
      try {
        beneath.ui.status(text)
      } catch {
        // an admin may withhold ui.status: the line simply is not drawn
      }
    }

    bindToasts(state, {
      now: () => beneath.clock.now(),
      show: (line, options) => beneath.ui.toast(line, options),
      after: (ms, fn) => beneath.clock.after(ms, fn),
      read: path => beneath.fs.read(`${state.root}/${path}`),
      write: (path, text) => beneath.fs.write(`${state.root}/${path}`, text),
      exists: path => beneath.fs.exists(`${state.root}/${path}`),
    })

    const ruflo: EngineInterface['ruflo'] = {
      segment: async input => {
        setSegment(state, input)
        redraw(state)
      },
      lastRoute: async () => (state.lastRoute ? { ...state.lastRoute } : null),
      snapshot: async () => snapshotOf(state),
    }

    // Beneath wins: if another step already added `ruflo`, ours never replaces it.
    const added = { ruflo }
    return { ...added, ...beneath }
  })
}

files.hooks/probe/index.ts:
import type { On } from 'claude-code'

import type { ModOptions } from '../options'
import type { ModState } from '../state'

/**
 * Capability probe (ADR-451 item 5): observability only. Off unless
 * `capabilityProbe` is on. It counts which of the events this module registered
 * fired, and keeps the engine version `$.session.version()`
 * reports, so `/ruflo-mods` can say "registered but never fired" when a build
 * renames or withholds an event. It reads no event payload, answers nothing,
 * writes nothing of its own and never changes, delays or denies a hook: each
 * event is handed on unchanged.
 */
export type ProbeState = {
  enabled: boolean
  /** Engine version as `$.session.version()` gave it; undefined when the build does not expose it. */
  version?: string
  /** Event names the module registered (pattern strings, ours, never payload). */
  registered: Set<string>
  fired: Map<string, number>
}

export const probeState = (): ProbeState => ({ enabled: false, registered: new Set(), fired: new Map() })

const MAX_LINE = 240

/**
 * The events this module registers, by name. The engine reads `on` calls
 * statically (it refuses a wrapped or aliased `on`), so the list is kept here;
 * tests/probe.test.ts fails when it drifts from what register() hooks under any option combination.
 */
const ALWAYS = ['command.run', 'engine.create', 'prompt.submit', 'session.end', 'session.start', 'tool.call', 'tool.check', 'turn.complete'] as const

type EventOptions = Pick<ModOptions, 'toolHints' | 'agentTrim' | 'deliveryScreen'> &
  Partial<Pick<ModOptions, 'compactCarry' | 'costBudgetUsd' | 'costHardStop' | 'sessionRollup' | 'modTrust'>>

export function registeredEvents(opts: EventOptions): string[] {
  const names: string[] = [...ALWAYS]
  // Registered only under these options, so "never fired" is not reported for an event the mod did not hook.
  if (opts.modTrust !== 'off') names.push('plugin.register')
  if (opts.costBudgetUsd !== undefined) names.push('session.measure')
  if ((opts.costBudgetUsd !== undefined && opts.costHardStop) || opts.sessionRollup || opts.agentTrim) names.push('agent.spawn')
  if (opts.toolHints) names.push('tool.describe')
  if (opts.agentTrim) names.push('agent.offer')
  if (opts.deliveryScreen) names.push('session.receive', 'session.send')
  if (opts.compactCarry) names.push('session.compact')
  return names.sort()
}

/**
 * One pass-through hook on every event: it counts the events the module
 * registered and hands the event on unchanged, answering nothing. Any failure
 * of its own passes the event on.
 */
export function registerProbe(on: On, state: ModState, opts: ModOptions) {
  state.probe.enabled = true
  for (const name of registeredEvents(opts)) state.probe.registered.add(name)
  on('*', ($, e, next) => {
    try {
      const name = (next as { event?: unknown }).event
      if (typeof name === 'string' && state.probe.registered.has(name)) state.probe.fired.set(name, (state.probe.fired.get(name) ?? 0) + 1)
    } catch {
      // counting must not change what any hook does
    }
    return next(e)
  }).catch(($, e, next) => next(e))
}

/** The version string kept from `$.session.version()`: printable, short; anything else is "not exposed". */
export function versionText(value: unknown): string | undefined {
  const { version, base } = (value ?? {}) as { version?: unknown; base?: unknown }
  const text = typeof base === 'string' && base ? base : version
  return typeof text === 'string' && /^[A-Za-z0-9._+-]{1,40}$/.test(text) ? text : undefined
}

/** The bounded status text the `probe:` row of `/ruflo-mods` shows (no label of its own: the report adds it). */
export function probeLine(probe: ProbeState): string {
  if (!probe.enabled) return 'off (set the capabilityProbe option)'
  const names = [...probe.registered].sort()
  const fired = names.filter(n => (probe.fired.get(n) ?? 0) > 0).length
  const never = names.filter(n => !probe.fired.get(n))
  const engine = probe.version ? `engine ${probe.version}` : 'engine version not exposed'
  const tail = never.length ? ` · never fired: ${never.join(', ')}` : ''
  const line = `${engine} · events fired ${fired}/${names.length}${tail}`
  return line.length > MAX_LINE ? `${line.slice(0, MAX_LINE - 1)}…` : line
}

