import type { EngineInterface, On } from 'claude-code'
import type { GuidanceHooks } from './guidance'

import { detectBrain } from './grounding'
import { versionText } from './probe'
import { HANDSHAKE_MARKER, ownedEvents } from './ownership'
import type { ModOptions } from './options'
import { ATTENTION_MAX_BYTES, ATTENTION_STATUS, attentionLine } from './attention'
import { MAX_BYTES, PROTECTOR_STATUS, protectorLine } from './protector'
import { redraw, report, under, type ModState } from './state'
import { bindToasts } from './toast'

/** `/ruflo-mods` plus the protector row when `.claude-flow/protector-mod/status.json` is present and readable (bounded, regular file only). */
/** The `attention:` row when the sessionAttention option is on and the console's summary file is a small regular file; never anything else. */
async function attentionRow($: EngineInterface, s: ModState, on: boolean): Promise<string | undefined> {
  if (!on) return undefined
  try {
    const path = under(s, ATTENTION_STATUS)
    const st = await $.fs.stat(path)
    if (st.kind !== 'file' || st.size > ATTENTION_MAX_BYTES) return undefined
    return attentionLine(await $.fs.read(path), await $.clock.now().catch(() => Date.now()))
  } catch {
    return undefined
  }
}

async function reportWithProtector($: EngineInterface, s: ModState, withAttention = false): Promise<string> {
  const extra = await attentionRow($, s, withAttention)
  const base = extra === undefined ? report(s) : `${report(s)}\n${extra}`
  try {
    const path = under(s, PROTECTOR_STATUS)
    const st = await $.fs.stat(path)
    if (st.kind !== 'file' || st.size > MAX_BYTES) return base
    const row = protectorLine(await $.fs.read(path))
    return row ? `${base}\n${row}` : base
  } catch {
    return base
  }
}

const HELPER = '.claude/helpers/hook-handler.cjs'

/**
 * Where the mod notes that it started and what it owns, for `ruflo mods
 * doctor` to read. Display only: nothing decides by it.
 */
export const HEARTBEAT_PATH = '.claude-flow/mods/session.json'

/**
 * Whether every hook-handler.cjs a classic hook could run honours the
 * handshake. Settings name the project's copy, `$HOME`'s, or probe one then
 * the other (settings-generator `hookCmd`), so both are checked: one copy too
 * old for the handshake is enough to stand down. Unreadable counts as too
 * old. With neither present no classic route/post-edit can run at all.
 */
async function helperHonours($: EngineInterface): Promise<boolean> {
  const root = await $.session.root().catch(() => undefined)
  const home = await $.env.get('HOME').catch(() => undefined)
  // The generated Windows command falls back to %USERPROFILE%\.claude\helpers when the project has no copy.
  const profile = await $.env.get('USERPROFILE').catch(() => undefined)
  for (const base of new Set([root, home, profile])) {
    if (!base) continue
    const path = `${base}/${HELPER}`
    if (!(await $.fs.exists(path).catch(() => true))) continue
    const text = await $.fs.read(path).catch(() => '')
    if (!text.includes(HANDSHAKE_MARKER)) return false
  }
  return true
}

/** ADR-485: the brain's status from installed_plugins.json and the merged settings; any failure is `unknown`. */
async function detectGrounding($: EngineInterface, settings: unknown) {
  try {
    const dir = (await $.env.get('CLAUDE_CONFIG_DIR').catch(() => undefined)) || `${(await $.env.get('HOME').catch(() => undefined)) ?? ''}/.claude`
    const path = `${dir}/plugins/installed_plugins.json`
    const stat = await $.fs.stat(path)

    if (stat.kind !== 'file' || stat.size > 2_000_000) return detectBrain(null, settings)

    return detectBrain(await $.fs.read(path), settings)
  } catch {
    return detectBrain(null, settings)
  }
}

/** Whether a ruflo statusLine is configured: then the mod draws none. */
function hasClassicStatusLine(settings: unknown): boolean {
  const command = (settings as { statusLine?: { command?: unknown } } | null)?.statusLine?.command
  return typeof command === 'string' && /statusline\.c?js/.test(command)
}

/**
 * At session start: decide which events the mod owns and tell the classic
 * hooks through the process environment; register `/ruflo-mods`. Any failure
 * leaves the mod owning nothing, so every classic hook keeps running.
 */
export function registerSession(on: On, state: ModState, options: ModOptions, guidance?: GuidanceHooks) {
  on('session.start', async ($, e, next) => {
    state.root = await $.session.root()
    bindToasts(state, {
      now: () => $.clock.now(),
      show: (line, options) => $.ui.toast(line, options),
      after: (ms, fn) => $.clock.after(ms, fn),
      read: path => $.fs.read(`${state.root}/${path}`),
      write: (path, text) => $.fs.write(`${state.root}/${path}`, text),
      exists: path => $.fs.exists(`${state.root}/${path}`),
    })
    // A user-scoped install loads in every project. Existing Ruflo state is
    // the opt-in boundary: a missing, unreadable or non-directory path must
    // neither own project events nor be created by the display heartbeat.
    const project = await $.fs.stat(under(state, '.claude-flow')).then(stat => stat.kind === 'dir').catch(() => false)
    const settings = await $.settings.read()
    state.owned = new Set(project ? ownedEvents(settings, await helperHonours($)) : [])
    await $.env.set('RUFLO_MODS_OWNS', state.owned.size ? [...state.owned].join(',') : undefined)
    state.statusLine = options.statusLine && !hasClassicStatusLine(settings)
    if (state.probe.enabled) state.probe.version = versionText(await $.session.version().catch(() => undefined))
    if (state.grounding.enabled) state.grounding.status = await detectGrounding($, settings)
    guidance?.start()
    redraw(state)
    await $.command
      .register({ name: 'ruflo-mods', description: 'Same as /ruflo mods: what this session routed, recorded and tightened' })
      .catch(() => undefined)
    if (project) {
      const heartbeat = { startedAt: new Date().toISOString(), owned: [...state.owned], statusLine: state.statusLine, ...(state.probe.enabled ? { engine: state.probe.version ?? null, events: [...state.probe.registered].sort() } : {}) }
      await $.fs.write(under(state, HEARTBEAT_PATH), `${JSON.stringify(heartbeat, null, 2)}\n`).catch(() => undefined)
    }
    return next(e)
  }).catch(async ($, e, next) => {
    state.owned = new Set()
    await $.env.set('RUFLO_MODS_OWNS', undefined).catch(() => undefined)
    try {
      $.ui.log(`ruflo mods: session start failed (${next.error.message ?? next.error.kind}); classic hooks keep every event`, {
        to: 'debug',
      })
    } catch {
      // a withheld ui.log changes nothing: the classic hooks already have every event
    }
    // Replay-safe: resolves to what the hook's own call settled to, or runs
    // the hooks beneath once when it never called.
    return next(e)
  })

  on('command.run', { command: 'ruflo-mods' }, async $ => ({ text: await reportWithProtector($, state, options.sessionAttention) }))

  // `/ruflo` is ruflo-console's one command for every ruflo mod; its `mods` subcommand is this report. The console
  // registers `/ruflo`; this hook answers `mods` wherever it sits in the chain and passes every other word on.
  // `/ruflo-mods` above stays registered as its alias: ADR-406 removes, renames or reassigns no command.
  // `/ruflo-console` is the same command as `/ruflo` (kept by ADR-406), so its `mods` is answered too.
  for (const command of ['ruflo', 'ruflo-console'] as const) {
    on('command.run', { command }, async ($, e, next) => (e.args.trim().split(/\s+/)[0]?.toLowerCase() === 'mods' ? { text: await reportWithProtector($, state, options.sessionAttention) } : next(e)))
  }
}

files.hooks/state.ts:
import type { BudgetLevel } from './cost/budget'
import type { ToastInput } from './toast/policy'
import type { EditRecord } from './learn/insights'
import { guidanceState, type GuidanceState } from './guidance/observations'
import type { Ownable } from './ownership'
import { rollupState, type RollupState } from './rollup'
import { ledgerLines } from './rollup/record'
import { groundingLine, groundingState, type GroundingState } from './grounding'
import { probeLine, probeState, type ProbeState } from './probe'
import type { RouteResult } from './route/route-task'

/**
 * What the mod knows during one process, shared by its features. In memory
 * only: it dies with the process, as the classic handshake variable does. A
 * hot reload re-runs `register` and `session.start`, which rebuild it; the
 * only state that would matter across a reload (pending edit records) is
 * written at every turn end, so a reload loses at most one turn's records.
 */
export type ModState = {
  /** The session's project root, where the classic helpers keep their files. */
  root: string
  owned: ReadonlySet<Ownable>
  /** Whether ruflo's own parts are shown (off where the ruflo statusLine helper runs). */
  statusLine: boolean
  lastRoute?: RouteResult
  routed: number
  tightened: number
  observed: number
  edits: EditRecord[]
  guidance: GuidanceState
  editCount: number
  policy: 'none' | 'observe' | 'enforce' | 'unreadable'
  /** The research run (marker startedAt) whose first web call was already put to the person. */
  researchAsked?: string
  budget: { level: BudgetLevel; usd?: number; limit?: number }
  /** `tool.describe` hints (ADR-451): whether the feature is on and which tools it described. */
  toolHints: { enabled: boolean; described: Set<string> }
  /** `agent.offer` trim (ADR-451): whether it is on, the types it hid, and the latest prompt (lower case). */
  agentTrim: { enabled: boolean; hidden: Set<string>; prompt: string; ledger?: Promise<Record<string, number>> }
  /** `session.receive`/`session.send` screen (ADR-451): whether it is on, deliveries consumed, sends refused. */
  delivery: { enabled: boolean; consumed: number; blocked: number }
  /** `session.compact` carry (ADR-451 item 7): whether it is on and how many compactions carried a block. */
  compact: { enabled: boolean; carried: number }
  /** Capability probe (ADR-451 item 5): engine version and which registered events fired. */
  probe: ProbeState
  /** Optional ruvnet-brain status (ADR-487): detect-only, off unless the grounding option is on. */
  grounding: GroundingState
  /** Session rollup (ADR-451 item 6): counters for the `$.store` ledger written at session end. */
  rollup: RollupState
  /** Other mods' status segments, by id (`$.ruflo.segment`). */
  segments: Map<string, string>
  /**
   * Draws the status line. Installed by the `engine.create` step from the `$`
   * beneath; a refused `ui.status` is swallowed, never failing a hook.
   */
  draw: (text: string | undefined) => void
  /** Says a toast through the shared policy (ADR-477). Installed by `engine.create`; never rejects; a no-op until then. */
  say: (input: ToastInput) => Promise<void>
}

export function createState(): ModState {
  return {
    root: '.',
    owned: new Set(),
    statusLine: false,
    routed: 0,
    tightened: 0,
    observed: 0,
    edits: [],
    guidance: guidanceState(),
    editCount: 0,
    policy: 'none',
    budget: { level: 'OK' },
    toolHints: { enabled: false, described: new Set() },
    agentTrim: { enabled: false, hidden: new Set(), prompt: '' },
    delivery: { enabled: false, consumed: 0, blocked: 0 },
    compact: { enabled: false, carried: 0 },
    probe: probeState(),
    grounding: groundingState(),
    rollup: rollupState(),
    segments: new Map(),
    draw: () => undefined,
    say: async () => undefined,
  }
}

/** A path under the session's project root. */
export const under = (s: ModState, relative: string) => `${s.root}/${relative}`

export const MAX_SEGMENTS = 8
export const MAX_SEGMENT_CHARS = 48
const SEGMENT_ID = /^[A-Za-z0-9_-]{1,32}$/

/**
 * Sets or clears one segment. Untrusted input: the id must be a short token,
 * the text loses control and bidi-override characters, collapses whitespace
 * and is cut to 48 characters. Throws (the caller's call rejects) on a bad id
 * or a new id past the cap.
 */
export function setSegment(s: ModState, input: unknown): void {
  const { id, text } = (input ?? {}) as { id?: unknown; text?: unknown }
  if (typeof id !== 'string' || !SEGMENT_ID.test(id)) throw new Error('ruflo.segment: id must be 1-32 of [A-Za-z0-9_-]')
  if (text !== null && typeof text !== 'string') throw new Error('ruflo.segment: text must be a string or null')
  const clean =
    text === null
      ? ''
      : text
          .replace(/\u001b\[[0-9;?]*[ -/]*[@-~]|\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)?/g, '')
          .replace(/[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁠-⁩﻿]/g, ' ')
          .replace(/\s+/g, ' ')
          .trim()
  if (!clean) {
    s.segments.delete(id)
    return
  }
  if (!s.segments.has(id) && s.segments.size >= MAX_SEGMENTS) throw new Error(`ruflo.segment: at most ${MAX_SEGMENTS} segments`)
  s.segments.set(id, clean.length > MAX_SEGMENT_CHARS ? `${clean.slice(0, MAX_SEGMENT_CHARS - 1)}…` : clean)
}

/** Segments as shown: sorted by id. */
export const sortedSegments = (s: ModState) => [...s.segments].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))

/**
 * The one status line: ruflo's own parts (when shown), then segments; or
 * undefined (clears the line) when there is nothing to show. Only measured
 * facts: a route that did not match says so, nothing is estimated.
 */
export function statusText(s: ModState): string | undefined {
  const parts: string[] = []
  if (s.statusLine) {
    if (s.lastRoute) {
      const pct = Math.round(s.lastRoute.confidence * 100)
      parts.push(s.lastRoute.matched ? `${s.lastRoute.agent} ${pct}%` : `no route (${pct}%)`)
    }
    if (s.editCount) parts.push(`${s.editCount} edit${s.editCount === 1 ? '' : 's'}`)
    if (s.policy !== 'none') parts.push(`policy ${s.policy}`)
    if (s.tightened) parts.push(`${s.tightened} tightened`)
    if (s.budget.limit !== undefined && s.budget.level !== 'OK') parts.push(`budget ${s.budget.level}`)
  }
  for (const [, text] of sortedSegments(s)) parts.push(text)
  return parts.length ? ['ruflo', ...parts].join(' · ') : undefined
}

/** Redraws the status line from the state. */
export const redraw = (s: ModState) => s.draw(statusText(s))

/** The projection state as a short fixed phrase; `unreadable` covers a hand-written legacy or unknown mode. */
const policyWord = (p: ModState['policy']) =>
  p === 'none' ? 'none' : p === 'unreadable' ? 'unreadable (rejected: calls ask)' : `${p} (projection read)`

/** What `/ruflo-mods` prints. */
export function report(s: ModState): string {
  const route = s.lastRoute
    ? `${s.lastRoute.agent} (${(s.lastRoute.confidence * 100).toFixed(0)}%, ${s.lastRoute.matched ? 'matched' : 'no match'})`
    : 'none yet'
  const budget =
    s.budget.limit === undefined
      ? 'off (set the costBudgetUsd option)'
      : `${s.budget.level}: $${(s.budget.usd ?? 0).toFixed(2)} of $${s.budget.limit.toFixed(2)}`
  const segments = sortedSegments(s).map(([id]) => id)
  return [
    'ruflo mods (ADR-404)',
    `  owns:        ${[...s.owned].join(', ') || 'nothing (classic hooks keep every event)'}`,
    `  routed:      ${s.routed} prompt(s); last ${route}`,
    `  edits:       ${s.editCount} recorded, ${s.edits.length} pending write`,
    `  policy:      ${policyWord(s.policy)}; ${s.tightened} call(s) tightened, ${s.observed} observed`,
    `  budget:      ${budget}`,
    `  tool hints:  ${s.toolHints.enabled ? `${s.toolHints.described.size} tool(s) described` : 'off (set the toolHints option)'}`,
    `  agent trim:  ${s.agentTrim.enabled ? `${s.agentTrim.hidden.size} type(s) hidden` : 'off (set the agentTrim option)'}`,
    `  delivery:    ${s.delivery.enabled ? `${s.delivery.consumed} dropped, ${s.delivery.blocked} refused` : 'off (set the deliveryScreen option)'}`,
    `  compact:     ${s.compact.enabled ? `${s.compact.carried} compaction(s) carried a block` : 'off (set the compactCarry option)'}`,
    `  probe:       ${probeLine(s.probe)}`,
    `  grounding:   ${groundingLine(s.grounding)}`,
    `  sessions:    ${s.rollup.enabled ? ledgerLines(s.rollup.recent).join('\n               ') : 'off (set the sessionRollup option)'}`,
    `  segments:    ${segments.join(', ') || 'none'}`,
    `  guidance:    ${s.guidance.status}; ${s.guidance.saved} unverified observation(s), ${s.guidance.pending.length} pending, ${s.guidance.dropped} dropped`,
  ]
    .concat(s.guidance.idsDropped + (s.guidance.active?.idsDropped ?? 0) > 0 ? [`               ${s.guidance.idsDropped + (s.guidance.active?.idsDropped ?? 0)} tool id(s) past the 256 cap not counted`] : [])
    .join('\n')
}

files.hooks/trust.ts:
import type { On } from 'claude-code'

/**
 * The mod trust gate (ADR-404). Claude Code can now write, install and
 * hot-reload a mod mid-session, and a mod runs with Claude Code's own access.
 * A user-tier hook on `plugin.register` judges every hooks module admitted
 * after it (and every reload), reading what the host scanned the module to
 * use; it may answer `{ refuse }`. This gate names what a module could do and,
 * only when the person opts in, refuses user-tier modules that can do the
 * risky things below. It reads the scan, never the module's own claims.
 *
 * What it cannot do: judge modules admitted before it (the host orders
 * admission), or any prepend/append/builtin module (the organization's and
 * Claude Code's own, out of a person's reach by design).
 */

export type TrustPolicy = 'observe' | 'refuse-risky' | 'off'

export type ModuleScan = {
  readonly name: string
  readonly tier: string
  readonly provenance: string
  readonly uses: { readonly events?: readonly string[]; readonly calls?: readonly string[]; readonly env?: unknown }
}

/** Calls that reach outside the session: commands, network, the environment. */
const RISKY_CALLS: Record<string, string> = {
  'process.run': 'runs host commands',
  'process.spawn': 'runs host commands',
  'http.fetch': 'makes network requests',
  'mcp.call': 'calls MCP tools (any connected server)',
  'mcp.connect': 'connects MCP servers',
  'session.send': 'sends messages to other agents',
  'config.set': 'changes Claude Code settings',
  'env.set': 'changes the environment of later hooks and tools',
  'fs.write': 'writes files (settings, hooks, helpers included)',
  'agent.spawn': 'starts agents with a prompt of its own',
}

/** Hooks that decide for, or over, everything else. */
const RISKY_EVENTS: Record<string, string> = {
  'tool.check': 'can answer tool permission verdicts',
  'tool.call': 'can rewrite or answer tool calls',
  '*': 'sees every event',
  'classic.*': 'can answer every settings hook',
  'plugin.register': 'can refuse other mods',
  'prompt.compose': 'can rewrite the system prompt',
  'prompt.submit': 'can add to or rewrite every prompt you send',
  'agent.spawn': 'can rewrite or answer every agent spawn',
}

/**
 * The risky events a registered pattern reaches. The scan reports patterns as
 * written, so a glob (`tool.*`) or a negation (`!tool.describe`: every event
 * but one) must be judged by what it selects, not by how it is spelled.
 */
const escapeRe = (text: string) => text.replace(/[.+?^$()|[\]{}\\]/g, '\\$&')

function riskyEventsOf(pattern: string): string[] {
  if (Object.hasOwn(RISKY_EVENTS, pattern)) return [pattern]
  if (pattern.startsWith('!')) return ['*']
  // A settings hook by name, or a glob of them, can answer any of them.
  if (pattern.startsWith('classic.')) return ['classic.*']
  if (!pattern.includes('*')) return []
  const glob = new RegExp(`^${pattern.split('*').map(escapeRe).join('.*')}$`)
  return Object.keys(RISKY_EVENTS).filter(name => name !== '*' && name !== 'classic.*' && glob.test(name))
}

const isStrings = (v: unknown): v is readonly string[] => Array.isArray(v) && v.every(s => typeof s === 'string')

/** What a module's scan says it could do that matters, as readable reasons. */
export function riskOf(scan: ModuleScan): string[] {
  const calls = isStrings(scan.uses?.calls) ? scan.uses.calls : []
  const events = isStrings(scan.uses?.events) ? scan.uses.events : []
  return [
    ...calls.filter(c => Object.hasOwn(RISKY_CALLS, c)).map(c => `${c} (${RISKY_CALLS[c]})`),
    ...events.flatMap(ev => riskyEventsOf(ev).map(name => `on ${ev === name ? ev : `${ev} → ${name}`} (${RISKY_EVENTS[name]})`)),
  ]
}

export type TrustDecision = { readonly judged: boolean; readonly risk: readonly string[]; readonly refuse?: string }

/**
 * Judges one registering module: user-tier modules not on the allow-list;
 * refusal only under `refuse-risky`. The allow-list matches the loader's
 * `provenance` (`name@marketplace`, `name@inline`), never the module's own
 * `name`, which is its manifest's word and a rename walks past. There is no
 * self-exemption: a module only judges those admitted after it, so ruflo-mods
 * never meets its own registration, and a mod calling itself "ruflo-mods" is
 * judged like any other.
 */
export function judge(scan: ModuleScan, policy: TrustPolicy, allow: ReadonlySet<string>): TrustDecision {
  if (policy === 'off' || scan.tier !== 'user' || allow.has(scan.provenance)) {
    return { judged: false, risk: [] }
  }
  const risk = riskOf(scan)
  return policy === 'refuse-risky' && risk.length > 0
    ? {
        judged: true,
        risk,
        refuse: `ruflo mod trust (modTrust=refuse-risky): ${scan.name} ${risk.join('; ')}; allow it by provenance (${scan.provenance}) in modTrustAllow`,
      }
    : { judged: true, risk }
}

/** The one line a person reads about a judged module. */
export const trustLine = (scan: ModuleScan, d: TrustDecision) =>
  `ruflo mod trust: ${scan.name} (${scan.provenance}) ${d.refuse ? 'REFUSED' : 'loaded'}${d.risk.length ? `; ${d.risk.join('; ')}` : '; no risky calls or hooks'}`

export function registerTrust(on: On, policy: TrustPolicy, allow: ReadonlySet<string>) {
  if (policy === 'off') return
  const told = new Set<string>()

  on('plugin.register', async ($, e, next) => {
    const decision = judge(e, policy, allow)
    if (!decision.judged) return next(e)
    // Keyed on what the module can do: a reload that gains a risky call or hook is named again.
    const key = `${e.provenance}:${decision.refuse ? 'refused' : 'loaded'}:${[...decision.risk].sort().join('|')}`
    if (!told.has(key)) {
      told.add(key)
      try {
        $.ui.log(trustLine(e, decision), decision.risk.length ? undefined : { to: 'debug' })
      } catch {
        // a withheld ui.log never decides admission
      }
    }
    return decision.refuse ? { refuse: decision.refuse } : next(e)
  }).catch(($, e, next) =>
    // Observing, a failure admits as Claude Code would without ruflo; set to
    // refuse, the gate guards something, so a module it could not judge stays out.
    policy === 'refuse-risky' && e.tier === 'user' && !allow.has(e.provenance)
      ? { refuse: `ruflo mod trust could not judge ${e.name} (${next.error.message ?? next.error.kind}); refused (modTrust=refuse-risky)` }
      : next(e),
  )
}

