import { anyWindow, scanWindows, windows } from '../guidance/screen'

/** Delivery origins that are the person's own or the lead's harness: never screened, so a screen cannot eat the user's prompt. */
const TRUSTED_ORIGINS: ReadonlySet<string> = new Set(['bridge', 'coordinator', 'scheduled-trigger'])

/**
 * Inbound-only rules beyond the shared injection screen, aimed at what a peer or relay sends to an agent: authority and goal
 * reassignment, mode switches, covert actions, prompt disclosure. Tighten-only, so an over-match costs one dropped delivery.
 */
const PEER_RULES: readonly (readonly [string, RegExp])[] = [
  ['mode switch', /\b(?:developer|god|dan|jailbreak(?:en)?|unrestricted) mode\b|\bno (?:limits|restrictions|filters)\b/i],
  ['goal replacement', /\byour (?:new|actual|real|true) (?:goal|task|mission|job|purpose)\b/i],
  ['authority reassignment', /\b(?:stop|do not|don't) following? the (?:user|operator|human)\b|\bfollow me instead\b|\btreat\b[^.\n]{0,40}\bmessages?\b[^.\n]{0,40}\b(?:from|as)\b[^.\n]{0,20}\b(?:user|operator|system|admin)\b|\bi (?:order|command) you\b/i],
  ['skip safeguards', /\b(?:skip|bypass|disable|circumvent)\b[^.\n]{0,25}\b(?:permissions?|safety|security|guards?|guardrails?|approvals?|safeguards?)\b|\bwithout asking (?:the )?(?:user|human|operator)\b/i],
  ['prompt disclosure', /\b(?:reveal|print|show|repeat|output|leak)\b[^.\n]{0,20}\b(?:your|the) (?:hidden |secret |full )?(?:system )?prompt\b/i],
  ['rules pretended away', /\bpretend\b[^.\n]{0,40}\b(?:rules?|polic(?:y|ies)|guidelines?|restrictions?)\b[^.\n]{0,20}\b(?:not exist|don't exist|do not exist|void)\b/i],
  ['covert action', /\b(?:silently|quietly|secretly|covertly)\b[^.\n]{0,30}\b(?:run|add|delete|remove|install|send|upload|write|execute|copy)\b/i],
]

const SSN = /\b\d{3}-\d{2}-\d{4}\b/

/** Whether a `session.receive` origin kind is screened. Unknown kinds are screened (the safe side for a tighten-only screen). */
export const isScreenedOrigin = (kind: string) => !TRUSTED_ORIGINS.has(kind)

/**
 * Rule id of the first injection phrase in an inbound delivery, or undefined.
 * Names only: the matched text is never returned. In-process, no network, no model.
 */
export function screenInbound(text: string): string | undefined {
  // The shared screen's windows, built once: invisible characters cannot split a phrase past the peer rules, and padding cannot hide one.
  const parts = windows(text)
  const shared = scanWindows(parts).injection[0]
  if (shared) return shared
  return PEER_RULES.find(([, re]) => anyWindow(parts, re))?.[0]
}

/** Rule id of the first secret shape (or US social security number) in an outbound message, or undefined. */
export function screenOutbound(text: string): string | undefined {
  const parts = windows(text)
  const found = scanWindows(parts)
  if (found.secrets.length) return found.secrets[0]
  return anyWindow(parts, SSN) ? 'us social security number' : undefined
}

files.hooks/describe/hints.ts:
/**
 * One-line usage hints for ruflo's own MCP tools (ADR-451). Every hint
 * restates what the project's CLAUDE.md already tells a person, so the model
 * sees it at the tool instead of only in a file it may not have loaded.
 * Static text only: `tool.describe` answers are cached for the session, and
 * an answer that changes spends the prompt cache.
 */
export const HINTS: Readonly<Record<string, string>> = {
  memory_search: 'Searches AgentDB only; memory_search_unified also covers Claude memories and patterns.',
  memory_store: 'Stores the value with a 384-dim ONNX embedding; give it a namespace.',
  swarm_init: 'For coding work use topology hierarchical, maxAgents 6-8, strategy specialized.',
  agent_spawn: 'Records the agent in ruflo coordination; Claude Code agents do the actual work.',
  hooks_route: 'Call before complex multi-file work to get the recommended agent and model tier.',
  guidance_brain: 'Call with mode recommend before complex ruflo work to read the live tool registry.',
}

/** The separator that marks a description a hint was already added to. */
export const MARK = '\n\nruflo: '

export const MAX_HINT_CHARS = 160

/** The server prefixes ruflo's MCP tools are listed under; nothing else is touched. */
export const RUFLO_TOOL_NAME = /^mcp__(?:plugin_ruflo-core_ruflo|claude-flow|ruflo)__([a-z0-9_-]+)$/

/** The hint for a tool as the model sees it by name, or undefined. */
export function hintFor(tool: string): string | undefined {
  const name = RUFLO_TOOL_NAME.exec(tool)?.[1]
  const hint = name === undefined ? undefined : Object.hasOwn(HINTS, name) ? HINTS[name] : undefined
  return hint !== undefined && hint.length <= MAX_HINT_CHARS ? hint : undefined
}

/** The description with the hint added once; anything unexpected is returned as it came. */
export function withHint(tool: string, description: unknown): unknown {
  if (typeof description !== 'string' || description.includes(MARK)) return description
  const hint = hintFor(tool)
  return hint === undefined ? description : `${description}${MARK}${hint}`
}

files.hooks/files.ts:
import type { FsStat } from 'claude-code'

/**
 * The two `$.fs` calls a reader needs. The engine reads a module's `$` uses
 * off its source, so `$` itself never leaves a hook: the hook builds this
 * from `$.fs.stat` / `$.fs.read` spelled at the call site.
 */
export type FileHost = {
  readonly stat: (path: string) => Promise<FsStat>
  readonly read: (path: string) => Promise<string>
}

/** Under `$.fs.read`'s own 4 MiB bound, so an oversized file reads as too big. */
export const MAX_READ_BYTES = 4 * 1024 * 1024

export type Read<T> =
  | { readonly kind: 'absent' }
  | { readonly kind: 'ok'; readonly value: T }
  | { readonly kind: 'error'; readonly message: string }

/**
 * Only ENOENT is "missing" (`$.fs.stat` rejects ENOENT for a missing path).
 * Anything else is an error: for the guard that means failing closed, so a
 * loosely matched message must never read as "no policy here".
 */
export const isMissing = (error: unknown, path?: string) => {
  const message = String((error as Error)?.message ?? error)
  // The path a message quotes is the caller's own word, not the error: a project under ".../ENOENT-x/" is not missing.
  return /\bENOENT\b/.test(path ? message.split(path).join('') : message)
}

/**
 * A reader that parses a project file once per change: one `$.fs.stat` per
 * call, a `$.fs.read` and parse only when its size or mtime moved. Absent is
 * a value, not an error; anything else that fails is `error`, which a guard
 * fails closed on.
 *
 * @param pathOf the file's path, resolved per call (it follows the session root)
 * @param parse turns the text into the value; may throw
 */
export function cachedFile<T>(pathOf: () => string, parse: (text: string) => T) {
  let seen: { key: string; read: Read<T> } | undefined

  return async (fs: FileHost): Promise<Read<T>> => {
    const path = pathOf()
    let key: string
    try {
      const stat = await fs.stat(path)
      if (stat.kind !== 'file') return { kind: 'error', message: `${path} is not a file` }
      if (stat.size > MAX_READ_BYTES) return { kind: 'error', message: `${path} is over 4 MiB` }
      key = `${path}:${stat.size}:${stat.mtimeMs}`
    } catch (error) {
      seen = undefined
      return isMissing(error, path) ? { kind: 'absent' } : { kind: 'error', message: messageOf(error) }
    }
    if (seen?.key === key) return seen.read

    const read = await readAndParse(fs, path, parse)
    seen = { key, read }
    return read
  }
}

const messageOf = (error: unknown) => String((error as Error)?.message ?? error)

/**
 * Only the read may say "absent": a parse error's message can quote the file's
 * own text (JSON.parse does), so a corrupt file containing "ENOENT" must still
 * be an error and never read as "no file here".
 */
async function readAndParse<T>(fs: FileHost, path: string, parse: (text: string) => T): Promise<Read<T>> {
  let text: string
  try {
    text = await fs.read(path)
  } catch (error) {
    return isMissing(error, path) ? { kind: 'absent' } : { kind: 'error', message: messageOf(error) }
  }
  try {
    return { kind: 'ok', value: parse(text) }
  } catch (error) {
    return { kind: 'error', message: messageOf(error) }
  }
}

files.hooks/guard/dangerous-command.ts:
import type { Verdict } from './verdict'

/**
 * The commands hook-handler.cjs `pre-bash` refuses. The root-delete entry
 * matches a root operand, not the prefix of every absolute path. The parity
 * tests exercise the same commands against the mod and classic helpers.
 */
export const DANGEROUS_COMMANDS: readonly string[] = ['rm -rf /', 'format c:', 'del /s /q c:\\', ':(){:|:&};:']

// Keep this literal-word scanner in sync with the classic helpers/fallback.
// It joins quote fragments and escapes, but never evaluates expansions or links.
function hasRootDelete(command: string, depth = 0): boolean {
  let word = '', quote = '', started = false, redirect = false
  let ansiNul = false // a NUL inside $'...' ends that string, as in bash
  let inRm = false, optionsEnded = false, recursive = false, force = false, root = false
  const isRoot = (operand: string) => {
    if (!operand.startsWith('/')) return false
    const parts: string[] = []
    for (const part of operand.split('/')) {
      if (!part || part === '.') continue
      if (part === '..') parts.pop()
      else parts.push(part)
    }
    return parts.length === 0 || /[*?\[]/.test(parts[0])
  }
  // One backslash escape inside $'...', from the character after the backslash.
  // Returns the text it stands for and the index of its last character. An unknown escape keeps its backslash.
  // The command arrives lowercased, so an uppercase-U escape reads as a lowercase one: eight digits starting 0000 are one code point.
  const ansiEscape = (s: string, at: number): [string, number] => {
    const c = s[at]
    const simple: Record<string, string> = { a: '\x07', b: '\b', e: '\x1b', f: '\f', n: '\n', r: '\r', t: '\t', v: '\v', '\\': '\\', "'": "'", '"': '"', '?': '?' }
    if (simple[c] !== undefined) return [simple[c], at]
    const digits = (from: number, max: number, pattern: RegExp) => pattern.exec(s.slice(from, from + max))?.[0]
    const octal = digits(at, 3, /^[0-7]+/)
    if (octal) return [String.fromCharCode(parseInt(octal, 8) & 255), at + octal.length - 1]
    const hex = c === 'x' ? digits(at + 1, 2, /^[0-9a-f]+/) : undefined
    if (hex) return [String.fromCharCode(parseInt(hex, 16)), at + hex.length]
    const wide = c === 'u' ? (digits(at + 1, 8, /^0000[0-9a-f]{4}$/) ?? digits(at + 1, 4, /^[0-9a-f]+/)) : undefined
    if (wide) return [String.fromCodePoint(parseInt(wide, 16)), at + wide.length]
    if (c === 'c' && at + 1 < s.length) return [String.fromCharCode(s.charCodeAt(at + 1) & 31), at + 1]
    return ['\\' + c, at]
  }
  const finishWord = () => {
    if (!started) return false
    // Literal shell strings (e.g. sh -c 'rm -rf /') also carried the old guard.
    // Bound rescanning to four levels; beyond that retain its conservative check.
    if (/[\s;&|()\x60]/.test(word)) {
      if (depth < 4 ? hasRootDelete(word, depth + 1) : word.includes('rm -rf /')) return true
    }
    if (!inRm) inRm = word === 'rm' || word.endsWith('/rm')
    else if (!optionsEnded && word === '--') optionsEnded = true
    else if (!optionsEnded && word.startsWith('-')) {
      // GNU getopt accepts any unambiguous long-option prefix: --r, --recur, --forc.
      recursive = recursive || (word.length > 2 && '--recursive'.startsWith(word)) || /^-[a-z]*r[a-z]*$/.test(word)
      force = force || (word.length > 2 && '--force'.startsWith(word)) || /^-[a-z]*f[a-z]*$/.test(word)
    } else root = root || isRoot(word)
    word = ''; started = false
    return inRm && recursive && force && root
  }
  // A command substitution's body, from just after its opening backtick. Bash removes a
  // backslash only before $, a backtick or a backslash (and " inside double quotes) and
  // drops backslash-newline; any other backslash stays for the nested scan.
  const substitution = (from: number, inDouble: boolean): [number, boolean] => {
    let body = '', j = from
    for (; j < command.length && command[j] !== '\x60'; j++) {
      const next = command[j + 1]
      if (command[j] === '\\' && j + 1 < command.length) {
        if (next === '\n') { j++; continue }
        if (next === '$' || next === '\x60' || next === '\\' || (inDouble && next === '"')) { body += next; j++; continue }
      }
      body += command[j]
    }
    return [j, depth < 4 ? hasRootDelete(body, depth + 1) : body.includes('rm -rf /')]
  }
  const finishCommand = () => {
    const denied = inRm && recursive && force && root
    inRm = optionsEnded = recursive = force = root = false
    return denied
  }
  for (let i = 0; i < command.length; i++) {
    const char = command[i]
    const redirectionAmpersand = char === '&' && (redirect || command[i + 1] === '>')
    redirect = false
    if (quote) {
      if (quote === "$'") {
        if (char === "'") { quote = ''; ansiNul = false }
        else if (char === '\\' && i + 1 < command.length) {
          const [text, last] = ansiEscape(command, i + 1)
          i = last
          if (!ansiNul) { const nul = text.indexOf('\0'); if (nul < 0) word += text; else { word += text.slice(0, nul); ansiNul = true } }
        } else if (!ansiNul) word += char
        continue
      }
      if (char === quote) quote = ''
      else if (quote === '"' && char === '\x60' && command.indexOf('\x60', i + 1) > i) {
        const [end, denied] = substitution(i + 1, true)
        if (denied) return true
        // The substitution is gone from the word, as bash's empty output is (a quoted empty substitution glued to -rf leaves -rf).
        // A # right after it is still inside the word: a placeholder keeps a rescan (sh -c "...")
        // from reading it as the start of a comment.
        if (command[end + 1] === '#') word += '\u0001'
        i = end
      }
      else if (quote === '"' && char === '\\' && i + 1 < command.length &&
        (command[i + 1] === '"' || command[i + 1] === '\\' || command[i + 1] === '$' ||
          command.charCodeAt(i + 1) === 96 || command[i + 1] === '\n')) {
        const next = command[++i]
        if (next !== '\n') word += next
      } else word += char
      continue
    }
    if (char === '\\' && i + 1 < command.length) {
      const next = command[++i]
      if (next !== '\n') { word += next; started = true }
    } else if (char === '\x60' && command.indexOf('\x60', i + 1) > i) {
      // Command substitution: scan the body as its own command; the substitution
      // stays inside the enclosing word, so the rm being parsed keeps its state,
      // and the word has started (a # right after it is not a comment).
      const [end, denied] = substitution(i + 1, false)
      if (denied) return true
      i = end; started = true
    } else if (char === '$' && (command[i + 1] === "'" || command[i + 1] === '"')) {
      // ANSI-C ($'...': escapes decoded) and locale ($"...") quoting: the $ is not part of the word.
      quote = command[i + 1] === "'" ? "$'" : '"'; started = true; i++
    } else if (char === '"' || char === "'") {
      quote = char; started = true
    } else if (char === '#' && !started) {
      while (i < command.length && command[i] !== '\n') i++
      if (finishCommand()) return true
    } else if (char === ' ' || char === '\t' || char === '\r' || char === '\n' ||
      ';|&()<>'.includes(char)) {
      if (finishWord()) return true
      // Redirections separate words, but later operands still belong to rm.
      redirect = char === '<' || char === '>'
      if (!redirectionAmpersand && (char === '\n' || ';|&()'.includes(char)) && finishCommand()) return true
    } else {
      word += char; started = true
    }
  }
  return finishWord() || finishCommand()
}

/**
 * A deny for a Bash call whose command is on the list, else undefined.
 *
 * @param tool the tool name as the model calls it
 * @param input the tool's arguments, unvalidated
 */
export function dangerousCommandVerdict(tool: string, input: unknown): Verdict | undefined {
  if (tool !== 'Bash') return undefined
  const raw = input !== null && typeof input === 'object' ? (input as { command?: unknown }).command : undefined
  // Same belt-and-braces as #2017: a non-string command is checked as text,
  // never skipped.
  const command = String(raw ?? '').toLowerCase()
  const hit = DANGEROUS_COMMANDS.find(d => d === 'rm -rf /' ? hasRootDelete(command) : command.includes(d))
  return hit === undefined
    ? undefined
    : { decision: 'deny', reason: `ruflo: dangerous command blocked (${hit})` }
}

files.hooks/guard/policy.ts:
import type { Verdict } from './verdict'

/**
 * Ruflo policy for Claude Code's own tool calls, read from the projection the
 * CLI writes beside the policy state (`.claude-flow/policy/claude-code.json`,
 * see cli/src/mods/policy-projection.ts) and never from state.json itself:
 * that file holds the receipt ledger (tens of MB) and is past the 4 MiB a hooks
 * module may read.
 *
 * Only rules whose `actions` name a `claude-code.` pattern explicitly take
 * part; a rule with no actions, or `*`, keeps meaning what it meant before
 * this mod existed (MCP calls only). Matching is engine.ts / evaluator.ts
 * `ruleMatches`, copied (a hooks module cannot import @claude-flow/security);
 * the parity test runs both over the same rules and requests. Only explicit
 * matches count: the engine's default-deny for an unmatched request does not
 * apply here, so turning the mod on never refuses a tool that no rule names.
 */

export const PROJECTION_PATH = '.claude-flow/policy/claude-code.json'
export const ACTION_PREFIX = 'claude-code.'

/** `legacy` is never projected: the CLI deletes the file for it, so a file that says so was hand-written (ADR-450 T10). */
export type PolicyMode = 'observe' | 'enforce'
type Effect = 'allow' | 'deny' | 'require_approval'

export type ProjectedRule = {
  readonly id: string
  readonly effect: Effect
  readonly actions: readonly string[]
  readonly enabled?: boolean
  readonly priority?: number
  readonly resources?: readonly string[]
  readonly principals?: readonly string[]
  readonly identityTypes?: readonly string[]
  readonly roles?: readonly string[]
  readonly environments?: readonly string[]
  readonly constraints?: Readonly<Record<string, unknown>>
}

export type Projection = { readonly mode: PolicyMode; readonly rules: readonly ProjectedRule[] }

export type ToolRequest = {
  readonly identity: { readonly id: string; readonly type: string; readonly roles?: readonly string[] }
  readonly action: {
    readonly type: string
    readonly resource?: string
    readonly environment?: string
    readonly network: boolean
    readonly destructive: boolean
    readonly namespace?: string
    readonly costUsd?: number
    readonly tokens?: number
    readonly concurrency?: number
  }
}

const MODES = new Set(['observe', 'enforce'])
const EFFECTS = new Set(['allow', 'deny', 'require_approval'])
const DESTRUCTIVE = new Set(['Bash', 'Write', 'Edit', 'MultiEdit', 'NotebookEdit'])
const NETWORK = new Set(['Bash', 'WebFetch', 'WebSearch'])

const isStrings = (v: unknown): v is string[] => Array.isArray(v) && v.every(s => typeof s === 'string')
const optStrings = (v: unknown) => v === undefined || isStrings(v)

/** Whether a rule speaks to Claude Code tool calls by name. */
export const targetsClaudeCode = (actions: readonly string[]) =>
  actions.some(a => a.startsWith(ACTION_PREFIX))

/**
 * Validates the projection's text. Throws on anything malformed: the caller
 * fails closed on a projection that exists but cannot be read.
 */
export function parseProjection(text: string): Projection {
  const raw: unknown = JSON.parse(text)
  if (raw === null || typeof raw !== 'object') throw new Error('projection is not an object')
  const { version, mode, rules } = raw as Record<string, unknown>
  if (version !== 1) throw new Error(`unsupported projection version ${String(version)}`)
  if (typeof mode !== 'string' || !MODES.has(mode)) throw new Error('projection mode invalid (only observe or enforce are ever written)')
  if (!Array.isArray(rules)) throw new Error('projection rules invalid')
  const valid = rules.map((r: unknown, i): ProjectedRule => {
    const rule = r as Record<string, unknown> | null
    const ok =
      rule !== null &&
      typeof rule === 'object' &&
      typeof rule.id === 'string' &&
      typeof rule.effect === 'string' &&
      EFFECTS.has(rule.effect) &&
      isStrings(rule.actions) &&
      optStrings(rule.resources) &&
      optStrings(rule.principals) &&
      optStrings(rule.identityTypes) &&
      optStrings(rule.roles) &&
      optStrings(rule.environments) &&
      (rule.priority === undefined || typeof rule.priority === 'number') &&
      (rule.constraints === undefined || (rule.constraints !== null && typeof rule.constraints === 'object'))
    if (!ok) throw new Error(`projection rule ${i} invalid`)
    return rule as unknown as ProjectedRule
  })
  return { mode: mode as PolicyMode, rules: valid.filter(r => targetsClaudeCode(r.actions)) }
}

/** The policy request for a Claude Code tool call. */
export function toolRequest(tool: string, input: unknown): ToolRequest {
  const args = input !== null && typeof input === 'object' ? (input as Record<string, unknown>) : {}
  const resource =
    typeof args.command === 'string' ? args.command
    : typeof args.file_path === 'string' ? args.file_path
    : typeof args.notebook_path === 'string' ? args.notebook_path
    : typeof args.url === 'string' ? args.url
    : tool
  return {
    identity: { id: 'claude-code', type: 'agent' },
    action: {
      type: `${ACTION_PREFIX}tool.${tool}`,
      resource,
      network: NETWORK.has(tool) || tool.startsWith('mcp__'),
      destructive: DESTRUCTIVE.has(tool),
    },
  }
}

function matches(patterns: readonly string[] | undefined, value: string | undefined): boolean {
  if (!patterns?.length) return true
  if (!value) return false
  return patterns.some(p => p === '*' || p === value || (p.endsWith('*') && value.startsWith(p.slice(0, -1))))
}

// evaluator.ts constraintsPass for a request that carries no evidence: a
// signed-evidence or provenance requirement can never be met here.
function constraintsPass(req: ToolRequest, c: Readonly<Record<string, unknown>> | undefined): boolean {
  if (!c) return true
  const a = req.action
  if (c.maxCostUsd !== undefined && (a.costUsd === undefined || a.costUsd > (c.maxCostUsd as number))) return false
  if (c.maxTokens !== undefined && (a.tokens === undefined || a.tokens > (c.maxTokens as number))) return false
  if (c.maxConcurrency !== undefined && (a.concurrency === undefined || a.concurrency > (c.maxConcurrency as number))) return false
  if (c.network === false && a.network === true) return false
  if (c.destructive === false && a.destructive === true) return false
  if (isStrings(c.allowedNamespaces) && c.allowedNamespaces.length && !matches(c.allowedNamespaces, a.namespace)) return false
  if (c.requireSignedEvidence) return false
  if (isStrings(c.requiredProvenance) && c.requiredProvenance.length) return false
  return true
}

/** evaluator.ts `ruleMatches`, over a projected rule. */
export function ruleMatches(rule: ProjectedRule, req: ToolRequest): boolean {
  if (rule.enabled === false) return false
  const { identity, action } = req
  return (
    matches(rule.actions, action.type) &&
    matches(rule.resources, action.resource) &&
    matches(rule.principals, identity.id) &&
    (!rule.identityTypes?.length || rule.identityTypes.includes(identity.type)) &&
    (!rule.roles?.length || rule.roles.some(role => identity.roles?.includes(role))) &&
    matches(rule.environments, action.environment) &&
    constraintsPass(req, rule.constraints)
  )
}

export type PolicyOpinion = { readonly verdict?: Verdict; readonly wouldBe?: string }

/**
 * Ruflo's opinion on a tool call: in `enforce`, a matched deny rule denies
 * and a matched approval rule asks; an allow rule says nothing (this mod
 * never loosens). In `observe`, `wouldBe` names what enforce would do.
 */
export function policyOpinion(projection: Projection, tool: string, input: unknown): PolicyOpinion {
  if (projection.rules.length === 0) return {}
  const req = toolRequest(tool, input)
  const matched = projection.rules
    .filter(rule => ruleMatches(rule, req))
    .sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0) || a.id.localeCompare(b.id))
  const deny = matched.find(r => r.effect === 'deny')
  const approval = matched.find(r => r.effect === 'require_approval')
  const verdict: Verdict | undefined = deny
    ? { decision: 'deny', reason: `ruflo policy: denied-by:${deny.id}` }
    : approval
      ? { decision: 'ask', reason: `ruflo policy: approval-required-by:${approval.id}` }
      : undefined
  if (!verdict) return {}
  return projection.mode === 'enforce' ? { verdict } : { wouldBe: verdict.reason }
}

